import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    n = int(data[0])
    right = [0] * 61
    left = [0] * 61

    idx = 1
    for _ in range(n):
        size = int(data[idx])
        side = data[idx + 1]
        idx += 2

        if side == b'D':
            right[size] += 1
        else:
            left[size] += 1

    pairs = 0
    for size in range(30, 61):
        pairs += min(right[size], left[size])

    print(pairs)

if __name__ == "__main__":
    main()
